$db->exec("CREATE TABLE IF NOT EXISTS return_requests(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,reference VARCHAR(40) NOT NULL UNIQUE,order_id BIGINT UNSIGNED NOT NULL,user_id BIGINT UNSIGNED NOT NULL,request_key VARCHAR(64) NOT NULL UNIQUE,status VARCHAR(30) NOT NULL DEFAULT 'requested',reason VARCHAR(30) NOT NULL,description TEXT NOT NULL,preferred_resolution VARCHAR(20) NOT NULL DEFAULT 'refund',eligibility_mode VARCHAR(30) NOT NULL,policy_snapshot JSON NOT NULL,admin_note TEXT NULL,internal_note TEXT NULL,return_tracking VARCHAR(120) NOT NULL DEFAULT '',resolution VARCHAR(30) NOT NULL DEFAULT '',refund_amount DECIMAL(12,2) NOT NULL DEFAULT 0,settlement_reference VARCHAR(160) NOT NULL DEFAULT '',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,INDEX idx_return_order(order_id),INDEX idx_return_user(user_id),FOREIGN KEY(order_id) REFERENCES orders(id),FOREIGN KEY(user_id) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS return_items(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,return_id BIGINT UNSIGNED NOT NULL,order_item_id BIGINT UNSIGNED NOT NULL,quantity INT UNSIGNED NOT NULL,UNIQUE KEY uq_return_item(return_id,order_item_id),FOREIGN KEY(return_id) REFERENCES return_requests(id),FOREIGN KEY(order_item_id) REFERENCES order_items(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS return_events(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,return_id BIGINT UNSIGNED NOT NULL,status VARCHAR(30) NOT NULL,note TEXT NOT NULL,actor_id BIGINT UNSIGNED NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(return_id) REFERENCES return_requests(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS return_evidence(id CHAR(32) PRIMARY KEY,order_id BIGINT UNSIGNED NOT NULL,user_id BIGINT UNSIGNED NOT NULL,return_id BIGINT UNSIGNED NULL,file_name VARCHAR(80) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(order_id) REFERENCES orders(id),FOREIGN KEY(return_id) REFERENCES return_requests(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;");
